64	export async function verifyToken(token: string): Promise<JWTPayload | null> {
65	  try {
66	    const { payload } = await jwtVerify(token, JWT_SECRET);
67	    return payload as unknown as JWTPayload;
68	  } catch {
69	    return null;
70	  }
71	}
