73	export async function setAuthCookie(token: string) {
74	  const cookieStore = await cookies();
75	  const days = await getConfigNumberClamped("jwt_expiry_days", 1, 365); // matches the JWT expiry
76	  const isSecure = process.env.NODE_ENV === "production" && process.env.SECURE_COOKIES === "true";
77	  cookieStore.set(AUTH_COOKIE_NAME, token, {
78	    httpOnly: true,
79	    secure: isSecure,
80	    sameSite: "lax",
81	    maxAge: 60 * 60 * 24 * days,
82	    path: "/",
83	  });
84	}
