95	export async function createPhoneVerificationChallenge(phone: string, code?: string, method?: string) {
96	  const payload: Record<string, unknown> = { phone };
97	  if (code) payload.codeHash = hashVerificationCode(code);
98	  if (method) payload.method = method;
99	
100	  return new SignJWT(payload)
101	    .setProtectedHeader({ alg: "HS256" })
102	    .setIssuedAt()
103	    .setExpirationTime("3m")
104	    .sign(JWT_SECRET);
105	}
