226	export async function getSession(options?: SessionOptions): Promise<SessionUser | null> {
227	  const session = await getJwtSession();
228	
229	  if (!session) {
230	    return null;
231	  }
232	
233	  if (options?.preferStudent && !isStudentRole(session.role)) {
234	    return null;
235	  }
236	
237	  return session;
238	}
