8	/** Cancel a pending (not-yet-executed) bulk deletion request. */
9	export async function DELETE(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
10	  const session = await getSession();
11	
12	    if (session && session.role === "superadmin") {
13	      try {
14	        await logAdminAction({
15	          adminId: session.id,
16	          adminName: session.name,
17	          action: "SUPERADMIN_ACTION",
18	          targetType: "API_ROUTE",
19	          targetId: req.nextUrl ? req.nextUrl.pathname : req.url,
20	          targetName: req.method,
21	        });
22	      } catch (e) {}
23	    }
24	  if (!session || !hasPermission(session.role, "bulk_delete_users")) {
25	    return NextResponse.json({ error: "غير مصرح" }, { status: 403 });
26	  }
27	
28	  try {
29	    const { id } = await params;
30	    const body = (await req.json().catch(() => ({}))) as { actionPassword?: string };
31	
32	    if (!verifyRoleActionPassword(session.role, body.actionPassword ?? "")) {
33	      return NextResponse.json({ error: "كلمة مرور المشرف غير صحيحة" }, { status: 401 });
34	    }
35	
36	    const request = await prisma.bulkDeletionRequest.findUnique({ where: { id } });
37	    if (!request || request.status !== "pending") {
38	      return NextResponse.json(
39	        { error: "الطلب غير موجود أو تم تنفيذه/إلغاؤه بالفعل" },
40	        { status: 404 }
41	      );
42	    }
43	
44	    await prisma.bulkDeletionRequest.update({
45	      where: { id },
46	      data: { status: "cancelled", cancelledAt: new Date() },
47	    });
48	
49	    await logAdminAction({
50	      adminId: session.id,
51	      adminName: session.name,
52	      action: LOG_ACTIONS.BULK_DELETE_CANCELLED,
53	      targetType: "bulk",
54	      targetId: id,
55	      targetName: isBulkScope(request.scope) ? scopeLabel(request.scope) : request.scope,
56	      metadata: { scope: request.scope },
57	    });
58	
59	    return NextResponse.json({ success: true });
60	  } catch (error) {
61	    console.error("Bulk-deletion cancel error:", error);
62	    return NextResponse.json({ error: "تعذر إلغاء طلب الحذف" }, { status: 500 });
63	  }
64	}

