67	// Just the env value — one place, no DB override, no "which password?" confusion.
68	export function verifyMasterPassword(password: string): boolean {
69	  const env = process.env.SUPERADMIN_MASTER_PASSWORD;
70	  if (!env || !password) return false;
71	  return timingSafeCompare(password, env);
72	}
