1	import { NextRequest, NextResponse } from "next/server";
2	import { getSession } from "@/lib/auth";
3	import { prisma } from "@/lib/prisma";
4	
5	/**
6	 * Teacher analytics overview. Scoped to the signed-in teacher's courses.
7	 * Query: ?period=7d|30d|90d|all  (default 30d)
8	 *
9	 * Returns KPIs with period-over-period deltas, daily views/enrollments series,
10	 * top & low-engagement videos, per-course breakdown, a quiz-score distribution,
11	 * and a prioritized "issues" feed (open tickets, unresolved feedback, recent
12	 * client errors, and data-health warnings like missing thumbnails / 0-view videos).
13	 */
14	
15	type PeriodKey = "7d" | "30d" | "90d" | "all";
16	const DAYS: Record<PeriodKey, number | null> = { "7d": 7, "30d": 30, "90d": 90, all: null };
17	
18	function dayKey(d: Date) {
19	  return d.toISOString().slice(0, 10);
20	}
21	
22	function delta(cur: number, prev: number) {
23	  if (prev <= 0) return cur > 0 ? 100 : 0;
24	  return Math.round(((cur - prev) / prev) * 100);
25	}
26	
27	export async function GET(req: NextRequest) {
28	  try {
29	  const session = await getSession();
30	  if (!session || session.role !== "teacher") {
31	    return NextResponse.json({ error: "غير مصرح" }, { status: 403 });
32	  }
33	  const teacherId = session.id;
34	
35	  const periodParam = (req.nextUrl.searchParams.get("period") || "30d") as PeriodKey;
36	  const days = DAYS[periodParam] ?? 30;
37	  const now = new Date();
38	  const periodStart = days ? new Date(now.getTime() - days * 86400000) : new Date(0);
39	  const prevStart = days ? new Date(periodStart.getTime() - days * 86400000) : new Date(0);
40	
41	  // Optional single-course filter (manual filter in the UI)
42	  const courseFilter = req.nextUrl.searchParams.get("courseId") || undefined;
43	
44	  // ── Teacher's courses + videos ──────────────────────────────────────────────
45	  const courses = await prisma.course.findMany({
46	    where: { teacherId, ...(courseFilter ? { id: courseFilter } : {}) },
47	    select: {
48	      id: true, title: true, thumbnailUrl: true,
49	      folders: {
50	        select: {
51	          id: true, name: true, publishAt: true,
52	          videos: { select: { id: true, title: true, durationMinutes: true, publishAt: true } },
53	        },
54	      },
55	    },
56	  });
57	
58	  const courseIds = courses.map((c) => c.id);
59	  const videoMeta = new Map<string, { title: string; course: string }>();
60	  const courseOfVideo = new Map<string, string>();
61	  for (const c of courses) {
62	    for (const f of c.folders) {
63	      const fTime = f.publishAt ? new Date(f.publishAt).getTime() : 0;
64	      for (const v of f.videos) {
65	        const vTime = v.publishAt ? new Date(v.publishAt).getTime() : 0;
66	        if (Math.max(fTime, vTime) <= now.getTime()) {
67	          videoMeta.set(v.id, { title: v.title, course: c.title });
68	          courseOfVideo.set(v.id, c.id);
69	        }
70	      }
71	    }
72	  }
73	  const videoIds = [...videoMeta.keys()];
74	
75	  if (courseIds.length === 0) {
76	    return NextResponse.json({
77	      teacherName: session.name,
78	      period: periodParam,
79	      empty: true,
80	      kpis: null,
81	      series: [],
82	      topVideos: [],
83	      lowVideos: [],
84	      courseBreakdown: [],
85	      quizBuckets: [],
86	      issues: [],
87	    });
88	  }
89	
90	  // ── Pull rows we need to bucket in JS (portable across DBs) ──────────────────
91	  const [watchRows, prevWatchCount, enrollRows, prevEnrollCount, completions, prevCompletions,
92	         quizRows, tickets, feedbacks, totalStudentsRows] = await Promise.all([
93	    prisma.videoWatchSession.findMany({
94	      where: { videoId: { in: videoIds }, startedAt: { gte: periodStart } },
95	      select: { videoId: true, startedAt: true },
96	    }),
97	    prisma.videoWatchSession.count({
98	      where: { videoId: { in: videoIds }, startedAt: { gte: prevStart, lt: periodStart } },
99	    }),
100	    prisma.accessCode.findMany({
101	      where: { courseId: { in: courseIds }, studentId: { not: null } },
102	      select: { usedAt: true, createdAt: true, studentId: true },
103	    }),
104	    prisma.accessCode.count({
105	      where: { courseId: { in: courseIds }, studentId: { not: null }, usedAt: { gte: prevStart, lt: periodStart } },
106	    }),
107	    prisma.progress.count({
108	      where: { videoId: { in: videoIds }, watched: true, watchedAt: { gte: periodStart } },
109	    }),
110	    prisma.progress.count({
111	      where: { videoId: { in: videoIds }, watched: true, watchedAt: { gte: prevStart, lt: periodStart } },
112	    }),
113	    prisma.quizResult.findMany({
114	      where: { quiz: { folder: { courseId: { in: courseIds } } }, completedAt: { gte: periodStart } },
115	      select: { score: true, totalQ: true },
116	    }),
117	    prisma.supportTicket.findMany({
118	      where: { courseId: { in: courseIds }, status: { not: "closed" } },
119	      select: { id: true, title: true, type: true, priority: true, status: true, createdAt: true },
120	      orderBy: { createdAt: "desc" }, take: 6,
121	    }),
122	    prisma.studentFeedback.findMany({
123	      where: { teacherId, isResolved: false },
124	      select: { id: true, type: true, content: true, rating: true, createdAt: true },
125	      orderBy: { createdAt: "desc" }, take: 6,
126	    }),
127	    // NOTE: platform technical errors (ClientError) are intentionally NOT shown
128	    // to teachers — that's the superadmin's error monitor. Teachers only see
129	    // student-facing issues (tickets, feedback) and their own content health.
130	    prisma.accessCode.findMany({
131	      where: { courseId: { in: courseIds }, studentId: { not: null } },
132	      select: { studentId: true },
133	    }),
134	  ]);
135	
136	  // ── KPIs ──────────────────────────────────────────────────────────────────
137	  const viewsCur = watchRows.length;
138	  const enrollEventAt = (r: { usedAt: Date | null; createdAt: Date }) => r.usedAt ?? r.createdAt;
139	  const enrollCur = enrollRows.filter((r) => enrollEventAt(r) >= periodStart).length;
140	  const totalStudents = new Set(totalStudentsRows.map((r) => r.studentId)).size;
141	
142	  // QuizResult.score is already a 0–100 percentage (correct/totalQ*100).
143	  const avgScore = quizRows.length
144	    ? Math.round(quizRows.reduce((a, q) => a + q.score, 0) / quizRows.length)
145	    : 0;
146	  // previous-period avg quiz score
147	  const prevQuiz = await prisma.quizResult.findMany({
148	    where: { quiz: { folder: { courseId: { in: courseIds } } }, completedAt: { gte: prevStart, lt: periodStart } },
149	    select: { score: true, totalQ: true },
150	  });
151	  const prevAvgScore = prevQuiz.length
152	    ? Math.round(prevQuiz.reduce((a, q) => a + q.score, 0) / prevQuiz.length)
153	    : 0;
154	
155	  const kpis = {
156	    students: { value: totalStudents, deltaPct: delta(enrollCur, prevEnrollCount), newThisPeriod: enrollCur },
157	    views: { value: viewsCur, deltaPct: delta(viewsCur, prevWatchCount) },
158	    completions: { value: completions, deltaPct: delta(completions, prevCompletions) },
159	    avgQuizScore: { value: avgScore, deltaPct: delta(avgScore, prevAvgScore) },
160	  };
161	
162	  // ── Daily series (views + enrollments) ──────────────────────────────────────
163	  const seriesDays = days ?? 30;
164	  const buckets = new Map<string, { date: string; views: number; enrollments: number }>();
165	  for (let i = seriesDays - 1; i >= 0; i--) {
166	    const d = new Date(now.getTime() - i * 86400000);
167	    buckets.set(dayKey(d), { date: dayKey(d), views: 0, enrollments: 0 });
168	  }
169	  for (const w of watchRows) {
170	    const b = buckets.get(dayKey(w.startedAt));
171	    if (b) b.views++;
172	  }
173	  for (const e of enrollRows) {
174	    const at = enrollEventAt(e);
175	    if (at >= periodStart) {
176	      const b = buckets.get(dayKey(at));
177	      if (b) b.enrollments++;
178	    }
179	  }
180	  const series = [...buckets.values()];
181	
182	  // ── Video engagement (views per video, in period) ────────────────────────────
183	  const viewsByVideo = new Map<string, number>();
184	  for (const id of videoIds) viewsByVideo.set(id, 0);
185	  for (const w of watchRows) viewsByVideo.set(w.videoId, (viewsByVideo.get(w.videoId) ?? 0) + 1);
186	
187	  const videoStats = [...viewsByVideo.entries()].map(([id, views]) => ({
188	    id,
189	    title: videoMeta.get(id)?.title ?? "—",
190	    course: videoMeta.get(id)?.course ?? "",
191	    views,
192	  }));
193	  const topVideos = [...videoStats].sort((a, b) => b.views - a.views).slice(0, 5);
194	  const lowVideos = [...videoStats].sort((a, b) => a.views - b.views).slice(0, 5);
195	
196	  // ── Per-course breakdown ─────────────────────────────────────────────────────
197	  const viewsByCourse = new Map<string, number>();
198	  for (const w of watchRows) {
199	    const cid = courseOfVideo.get(w.videoId);
200	    if (cid) viewsByCourse.set(cid, (viewsByCourse.get(cid) ?? 0) + 1);
201	  }
202	  const studentsByCourse = await prisma.accessCode.groupBy({
203	    by: ["courseId"],
204	    where: { courseId: { in: courseIds }, studentId: { not: null } },
205	    _count: { studentId: true },
206	  });
207	  const studentCountMap = new Map(studentsByCourse.map((s) => [s.courseId, s._count.studentId]));
208	  const courseBreakdown = courses.map((c) => ({
209	    id: c.id,
210	    title: c.title,
211	    students: studentCountMap.get(c.id) ?? 0,
212	    views: viewsByCourse.get(c.id) ?? 0,
213	  })).sort((a, b) => b.views - a.views);
214	
215	  // ── Quiz score distribution ──────────────────────────────────────────────────
216	  const bucketsDef = [
217	    { label: "0–49٪", min: 0, max: 50 },
218	    { label: "50–69٪", min: 50, max: 70 },
219	    { label: "70–84٪", min: 70, max: 85 },
220	    { label: "85–100٪", min: 85, max: 101 },
221	  ];
222	  const quizBuckets = bucketsDef.map((b) => ({
223	    label: b.label,
224	    count: quizRows.filter((q) => q.score >= b.min && q.score < b.max).length,
225	  }));
226	
227	  // ── Issues feed ──────────────────────────────────────────────────────────────
228	  type Issue = { kind: string; severity: "high" | "med" | "low"; title: string; detail: string; at: string | null };
229	  const issues: Issue[] = [];
230	
231	  for (const t of tickets) {
232	    issues.push({
233	      kind: "ticket",
234	      severity: t.priority === "high" || t.priority === "urgent" ? "high" : "med",
235	      title: "تذكرة دعم من متعلم",
236	      detail: t.title,
237	      at: t.createdAt.toISOString(),
238	    });
239	  }
240	  for (const f of feedbacks) {
241	    issues.push({
242	      kind: "feedback",
243	      severity: (f.rating ?? 5) <= 2 ? "high" : "low",
244	      title: f.type === "complaint" ? "شكوى من متعلم" : "ملاحظة من متعلم",
245	      detail: f.content.slice(0, 120),
246	      at: f.createdAt.toISOString(),
247	    });
248	  }
249	  // Surfacing grading queue (Gap 30)
250	  const teacherLessonIds = (await prisma.planLessonSource.findMany({
251	    where: { teacherId: session.id },
252	    select: { planLessonId: true }
253	  })).map(s => s.planLessonId);
254	
255	  const pendingGradingCount = await prisma.planProjectSubmission.count({
256	    where: {
257	      status: "pending",
258	      planLessonId: { in: teacherLessonIds }
259	    }
260	  });
261	  if (pendingGradingCount > 0) {
262	    issues.push({
263	      kind: "grading",
264	      severity: "high",
265	      title: "مشاريع معلقة بانتظار التقييم",
266	      detail: `توجد عدد ${pendingGradingCount} مشروع معلق يتطلب مراجعتك وتقييمك.`,
267	      at: null,
268	    });
269	  }
270	
271	  // Data-health warnings
272	  for (const c of courses) {
273	    if (!c.thumbnailUrl || !/^https?:\/\//i.test(c.thumbnailUrl)) {
274	      issues.push({ kind: "health", severity: "med", title: "صورة الكورس مفقودة أو غير صالحة", detail: c.title, at: null });
275	    }
276	    const allVideos = c.folders.flatMap((f) => f.videos);
277	    const noDuration = allVideos.filter((v) => !v.durationMinutes).length;
278	    if (allVideos.length > 0 && noDuration > 0) {
279	      issues.push({ kind: "health", severity: "low", title: "فيديوهات بدون مدة محددة (لا يظهر تقدّم الطالب)", detail: `${c.title} — ${noDuration} فيديو`, at: null });
280	    }
281	    const emptyFolders = c.folders.filter((f) => f.videos.length === 0).length;
282	    if (emptyFolders > 0) {
283	      issues.push({ kind: "health", severity: "low", title: "محاضرات فارغة بدون محتوى", detail: `${c.title} — ${emptyFolders} محاضرة`, at: null });
284	    }
285	  }
286	  const zeroViewVideos = videoStats.filter((v) => v.views === 0).length;
287	  if (zeroViewVideos > 0 && videoIds.length > 0) {
