291	      detail: `${zeroViewVideos} من ${videoIds.length} فيديو`, at: null,
292	    });
293	  }
294	
295	  const sevRank = { high: 0, med: 1, low: 2 };
296	  issues.sort((a, b) => sevRank[a.severity] - sevRank[b.severity]);
297	
298	  return NextResponse.json({
299	    teacherName: session.name,
300	    period: periodParam,
301	    empty: false,
302	    kpis,
303	    series,
304	    topVideos,
305	    lowVideos,
306	    courseBreakdown,
307	    quizBuckets,
308	    issues: issues.slice(0, 12),
309	    totals: { courses: courseIds.length, videos: videoIds.length },
310	  });
311	} catch (error) {
312	    console.error("[admin/analytics] error:", error);
313	    return NextResponse.json(
314	      { error: "حدث خطأ داخلي" },
315	      { status: 500 }
316	    );
317	  }
318	}

