7	async function uniqueSlug(name: string, teacherId: string): Promise<string> {
8	  let base = slugify(name);
9	  if (!isValidSlug(base)) base = "teacher";
10	  let candidate = base;
11	  let n = 2;
12	  // Find a free slug (ignore the teacher's own row).
13	  while (true) {
14	    const taken = await prisma.teacherProfile.findFirst({
15	      where: { slug: candidate, NOT: { teacherId } },
16	      select: { id: true },
17	    });
18	    if (!taken) return candidate;
19	    candidate = `${base}-${n++}`;
20	  }
21	}
