1	import { timingSafeEqual } from "crypto";
2	import { prisma } from "./prisma";
3	import { getConfigNumberClamped } from "./config";
4	
5	/**
6	 * Bulk account deletion — the superadmin "danger zone".
7	 *
8	 * Flow:
9	 *  - A request targets a scope: "students", "teachers", or "all" (= both).
10	 *    Admins, staff and superadmins are NEVER touched, regardless of scope.
11	 *  - Scheduled requests wait GRACE_DAYS before the accounts are soft-deleted;
12	 *    they can be cancelled any time during the wait. Accounts stay fully active
13	 *    until the soft-delete runs.
14	 *  - Instant requests (gated by BULK_DELETE_PASSWORD) soft-delete immediately.
15	 *  - Soft-deleted users land in the existing trash (DeletedStudents/Teachers),
16	 *    where the superadmin can restore them. After PURGE_DAYS they are removed
17	 *    permanently (teachers' courses go with them).
18	 *
19	 * No cron is required: runBulkMaintenance() is called lazily whenever the
20	 * superadmin touches the bulk-deletion endpoints, and can also be hit by a
21	 * server cron via the maintenance endpoint.
22	 */
23	
24	export const GRACE_DAYS = 7; // scheduled wait before soft-delete
25	const DAY_MS = 86_400_000;
26	
27	/** Recoverable window before permanent purge — superadmin-configurable (was 30). */
28	export async function getPurgeDays(): Promise<number> {
29	  // Clamp to ≥1 day so a stray 0 can never purge everything instantly.
30	  return getConfigNumberClamped("trash_purge_days", 1);
31	}
32	
33	export type BulkScope = "all" | "students" | "teachers";
34	/** Roles a bulk request may ever delete. Superadmin/admin/staff are excluded. */
35	const SCOPE_ROLES: Record<BulkScope, string[]> = {
36	  all: ["student", "teacher"],
37	  students: ["student"],
38	  teachers: ["teacher"],
39	};
40	
41	export function isBulkScope(v: unknown): v is BulkScope {
42	  return v === "all" || v === "students" || v === "teachers";
43	}
44	
45	export function scopeRoles(scope: BulkScope): string[] {
46	  return SCOPE_ROLES[scope];
47	}
48	
49	const SCOPE_LABEL: Record<BulkScope, string> = {
50	  all: "كل المتعلمين والمعلمين",
51	  students: "كل المتعلمين",
52	  teachers: "كل المعلمين",
53	};
54	export function scopeLabel(scope: BulkScope): string {
55	  return SCOPE_LABEL[scope];
56	}
57	
58	// ─── Instant-delete password ──────────────────────────────────────────────────
59	
60	function safeEqual(a: string, b: string): boolean {
61	  try {
62	    const ab = Buffer.from(a, "utf8");
63	    const bb = Buffer.from(b, "utf8");
64	    if (ab.length !== bb.length) return false;
65	    return timingSafeEqual(ab, bb);
66	  } catch {
67	    return false;
68	  }
69	}
70	
71	/** True only when BULK_DELETE_PASSWORD is set AND matches. */
72	export function verifyBulkDeletePassword(password: string): boolean {
73	  const env = process.env.BULK_DELETE_PASSWORD;
74	  if (!env || !password) return false;
75	  return safeEqual(password, env);
76	}
77	
78	export function bulkDeletePasswordConfigured(): boolean {
79	  return !!process.env.BULK_DELETE_PASSWORD;
80	}
81	
82	// ─── Counting / preview ─────────────────────────────────────────────────────
83	
84	/** How many live (non-deleted) accounts a scope would affect right now. */
85	export async function countScope(scope: BulkScope): Promise<number> {
86	  return prisma.user.count({
87	    where: { role: { in: scopeRoles(scope) }, isDeleted: false },
88	  });
89	}
90	
91	// ─── Soft delete ────────────────────────────────────────────────────────────
92	
93	/**
94	 * Soft-deletes every live account in scope (sets isDeleted/deletedAt, blocks
95	 * login). Returns the number affected. `exceptId` is always spared.
96	 */
97	export async function softDeleteScope(scope: BulkScope, exceptId?: string): Promise<number> {
98	  const res = await prisma.user.updateMany({
99	    where: {
100	      role: { in: scopeRoles(scope) },
101	      isDeleted: false,
102	      ...(exceptId ? { id: { not: exceptId } } : {}),
103	    },
104	    data: { isDeleted: true, deletedAt: new Date(), isActive: false },
105	  });
106	  return res.count;
107	}
108	
109	// ─── Maintenance: execute due requests + purge expired ────────────────────────
110	
111	/** Runs any pending request whose executeAt has passed. */
112	export async function runDueBulkDeletions(): Promise<number> {
113	  const due = await prisma.bulkDeletionRequest.findMany({
114	    where: { status: "pending", executeAt: { lte: new Date() } },
115	  });
116	  let executed = 0;
117	  for (const req of due) {
118	    if (!isBulkScope(req.scope)) continue;
119	    const affected = await softDeleteScope(req.scope, req.requestedById);
120	    await prisma.bulkDeletionRequest.update({
121	      where: { id: req.id },
122	      data: { status: "executed", executedAt: new Date(), affectedCount: affected },
123	    });
124	    executed += 1;
125	  }
126	  return executed;
127	}
128	
129	/**
130	 * Permanently removes student/teacher accounts soft-deleted more than
131	 * PURGE_DAYS ago. Teachers' courses are deleted first (FK safety). Superadmins
132	 * are never purged.
133	 */
134	export async function purgeExpiredDeletedUsers(): Promise<number> {
135	  const purgeDays = await getConfigNumberClamped("trash_purge_days", 1);
136	  const cutoff = new Date(Date.now() - purgeDays * DAY_MS);
137	  const expired = await prisma.user.findMany({
138	    where: {
139	      role: { in: ["student", "teacher"] },
140	      isDeleted: true,
141	      deletedAt: { lt: cutoff },
142	    },
143	    select: { id: true, role: true },
144	  });
145	  if (expired.length === 0) return 0;
146	
147	  const teacherIds = expired.filter((u) => u.role === "teacher").map((u) => u.id);
148	  if (teacherIds.length > 0) {
149	    await prisma.course.deleteMany({ where: { teacherId: { in: teacherIds } } });
150	  }
151	  const ids = expired.map((u) => u.id);
152	  await prisma.user.deleteMany({ where: { id: { in: ids } } });
153	  return ids.length;
154	}
155	
156	/** Lazy maintenance hook — safe to call on every superadmin request. */
157	export async function runBulkMaintenance(): Promise<{ executed: number; purged: number }> {
158	  const executed = await runDueBulkDeletions();
159	  const purged = await purgeExpiredDeletedUsers();
160	  return { executed, purged };
161	}

