40	    const recordFailedAttempt = async () => {
41	      const newTries = currentTries + 1;
42	      await prisma.appSetting.upsert({
43	        where: { key: failedTriesKey },
44	        update: { value: String(newTries) },
45	        create: { key: failedTriesKey, value: String(newTries) },
46	      });
