61	    // Two ways in (password-only form, so we match by password):
62	    //   1. Break-glass: the env master password → owner-level session (no DB row).
63	    //   2. A named DB-backed superadmin whose bcrypt password matches.
64	    if (role === "superadmin") {
65	      if (!password) {
66	        return NextResponse.json({ error: "كلمة المرور مطلوبة" }, { status: 400 });
67	      }
68	
69	      // 1) Break-glass owner login — DB-set master password (or env fallback).
70	      if (await verifyMasterPassword(password)) {
