44	  return pathname === "/api/plans" || /^\/api\/plans\/[^/]+$/.test(pathname);
45	}
46	
47	function startsWithAny(pathname: string, prefixes: string[]) {
48	  return prefixes.some((prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`));
49	}
50	
51	/** /adminpanel login page itself — exact match only, never prefix */
52	function isAdminLoginPage(pathname: string) {
53	  return pathname === "/adminpanel" || pathname === "/adminpanel/";
54	}
