56	// Read JWT_SECRET dynamically inside hasValidSession to handle hot-reloads and Edge runtime environment injection correctly.
57	async function hasValidSession(req: NextRequest) {
58	  const secretStr = process.env.JWT_SECRET;
59	  if (!secretStr) {
60	    console.warn("JWT_SECRET environment variable is missing in middleware context!");
61	    return false;
62	  }
63	  const token = req.cookies.get("auth_token")?.value;
64	  if (!token) {
65	    return false;
66	  }
67	  try {
68	    const secret = new TextEncoder().encode(secretStr);
69	    await jwtVerify(token, secret);
70	    return true;
71	  } catch (err: any) {
72	    return false;
73	  }
74	}
