76	export default async function proxy(req: NextRequest) {
77	  const pathname = req.nextUrl.pathname;
78	
79	  // Forward the current path to server components (root layout reads this to
80	  // decide maintenance gating — middleware runs on Edge and can't touch the DB).
81	  const requestHeaders = new Headers(req.headers);
82	  requestHeaders.set("x-pathname", pathname);
83	  const pass = () => NextResponse.next({ request: { headers: requestHeaders } });
84	
85	  if (pathname === "/") return pass();
86	
87	  // Admin panel login page — always public
88	  if (isAdminLoginPage(pathname)) return pass();
89	
90	  // Always allow public access to login and signup
91	  if (pathname.startsWith("/login") || pathname.startsWith("/signup")) {
92	    return pass();
93	  }
94	
95	  const authed = await hasValidSession(req);
96	
97	  // Admin sub-pages: redirect to /adminpanel login if no session
98	  if (startsWithAny(pathname, ADMIN_PANEL_PREFIXES) && !authed) {
99	    return NextResponse.redirect(new URL("/adminpanel", req.url));
100	  }
101	
102	  // Learning room inside courses — auth required
103	  if (isProtectedCourseRoute(pathname) && !authed) {
104	    const loginUrl = new URL("/login", req.url);
105	    loginUrl.searchParams.set("redirect_url", pathname);
106	    return NextResponse.redirect(loginUrl);
107	  }
108	
109	  // Learning room inside plans — auth required
110	  if (isProtectedPlanRoute(pathname) && !authed) {
111	    const loginUrl = new URL("/login", req.url);
112	    loginUrl.searchParams.set("redirect_url", pathname);
113	    return NextResponse.redirect(loginUrl);
114	  }
115	
116	  // Protect /api/courses/* except public preview endpoint
117	  if (pathname.startsWith("/api/courses") && !isPublicCoursesApi(pathname) && !authed) {
118	    return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
119	  }
120	
121	  // Protect /api/plans/* except public endpoints
122	  if (pathname.startsWith("/api/plans") && !isPublicPlansApi(pathname) && !authed) {
123	    return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
124	  }
125	
126	  // Protect other API endpoints (return 401 JSON, NEVER redirect to /login HTML)
127	  if (startsWithAny(pathname, PROTECTED_API_PREFIXES) && !authed) {
128	    return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
129	  }
130	
131	  // Protected page routes: redirect to /login if no session
132	  if (startsWithAny(pathname, PROTECTED_PAGE_PREFIXES) && !authed) {
133	    const loginUrl = new URL("/login", req.url);
134	    loginUrl.searchParams.set("redirect_url", pathname);
135	    return NextResponse.redirect(loginUrl);
136	  }
137	
138	  return pass();
139	}
