1	import { createCipheriv, createDecipheriv, createHash, randomBytes } from "node:crypto";
2	import { prisma } from "./prisma";
3	
4	/**
5	 * AI provider management. API keys are encrypted with AES-256-GCM before they
6	 * touch the database and are NEVER returned to the client — getActiveProviders()
7	 * exposes only a `hasKey` boolean. Decryption happens server-side, only inside
8	 * AI request handlers, via getDecryptedKey().
9	 */
10	
11	// ── Encryption ──────────────────────────────────────────────────────────────
12	// The 32-byte AES key is derived (sha256) from CONFIG_ENCRYPTION_KEY so any
13	// passphrase length works; the env var itself never lands in the DB.
14	function aesKey(): Buffer {
15	  const secret = process.env.CONFIG_ENCRYPTION_KEY;
16	  if (!secret) throw new Error("CONFIG_ENCRYPTION_KEY is not set");
17	  return createHash("sha256").update(secret).digest();
18	}
19	
20	/** Returns "iv:authTag:ciphertext" (all base64). */
21	export function encryptSecret(plaintext: string): string {
22	  // Refuse to encrypt under a weak passphrase. SHA-256 gives no key-stretching,
23	  // so the security is only as strong as this string — require ≥32 chars.
24	  const secret = process.env.CONFIG_ENCRYPTION_KEY ?? "";
25	  if (secret.length < 32) {
26	    throw new Error("CONFIG_ENCRYPTION_KEY must be at least 32 characters (use a long random string)");
27	  }
28	  const iv = randomBytes(12);
29	  const cipher = createCipheriv("aes-256-gcm", aesKey(), iv);
30	  const enc = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
31	  const tag = cipher.getAuthTag();
32	  return `${iv.toString("base64")}:${tag.toString("base64")}:${enc.toString("base64")}`;
33	}
34	
35	function decryptSecret(payload: string): string {
36	  const [ivB64, tagB64, dataB64] = payload.split(":");
37	  if (!ivB64 || !tagB64 || !dataB64) throw new Error("Malformed ciphertext");
38	  const decipher = createDecipheriv("aes-256-gcm", aesKey(), Buffer.from(ivB64, "base64"));
39	  decipher.setAuthTag(Buffer.from(tagB64, "base64"));
40	  return Buffer.concat([decipher.update(Buffer.from(dataB64, "base64")), decipher.final()]).toString("utf8");
41	}
42	
43	export function encryptionConfigured(): boolean {
44	  return (process.env.CONFIG_ENCRYPTION_KEY?.length ?? 0) >= 32;
45	}
46	
47	// ── Public (no-secret) shapes ────────────────────────────────────────────────
48	export interface PublicProvider {
49	  id: string;
50	  name: string;
51	  slug: string;
52	  baseUrl: string;
53	  models: string[];
54	  hasKey: boolean;
55	  isPrimary: boolean;
56	  isBackup: boolean;
57	  isActive: boolean;
58	}
59	
60	function toPublic(p: {
61	  id: string; name: string; slug: string; baseUrl: string; models: string;
62	  apiKeyEnc: string | null; isPrimary: boolean; isBackup: boolean; isActive: boolean;
63	}): PublicProvider {
64	  let models: string[] = [];
65	  try {
66	    const parsed = JSON.parse(p.models);
67	    if (Array.isArray(parsed)) models = parsed.map(String);
68	  } catch {
69	    /* leave empty */
70	  }
71	  return {
72	    id: p.id,
73	    name: p.name,
74	    slug: p.slug,
75	    baseUrl: p.baseUrl,
76	    models,
77	    hasKey: !!p.apiKeyEnc, // never the key itself
78	    isPrimary: p.isPrimary,
79	    isBackup: p.isBackup,
80	    isActive: p.isActive,
81	  };
82	}
