84	/** All providers, keys stripped — safe to send to the client. */
85	export async function getActiveProviders(): Promise<PublicProvider[]> {
86	  try {
87	    const rows = await prisma.aIProvider.findMany({ orderBy: [{ isPrimary: "desc" }, { createdAt: "asc" }] });
88	    return rows.map(toPublic);
89	  } catch {
90	    return []; // table missing / db error → empty list, no crash
91	  }
92	}
