94	export function normalizeModels(models: unknown): string {
95	  if (Array.isArray(models)) {
96	    return JSON.stringify(models.map((m) => String(m).trim()).filter(Boolean));
97	  }
98	  if (typeof models === "string") {
99	    return JSON.stringify(
100	      models.split(/[\n,]/).map((m) => m.trim()).filter(Boolean)
101	    );
102	  }
103	  return "[]";
104	}
