106	// ── Server-only secret access ────────────────────────────────────────────────
107	/** Decrypts a provider's key. Server-only; never call from client code. */
108	export async function getDecryptedKey(providerId: string): Promise<string | null> {
109	  const p = await prisma.aIProvider.findUnique({ where: { id: providerId }, select: { apiKeyEnc: true } });
110	  if (!p?.apiKeyEnc) return null;
111	  try {
112	    return decryptSecret(p.apiKeyEnc);
113	  } catch {
114	    return null;
115	  }
116	}
