118	/** Detected request shape for a provider, from its base URL. */
119	export type ProviderKind = "anthropic" | "gemini" | "openai";
120	export function providerKind(baseUrl: string): ProviderKind {
121	  const u = baseUrl.toLowerCase();
122	  if (u.includes("anthropic")) return "anthropic";
123	  if (u.includes("googleapis") || u.includes("generativelanguage")) return "gemini";
124	  return "openai";
125	}
126	
127	export interface ResolvedProvider {
128	  id: string;
129	  name: string;
130	  baseUrl: string;
131	  model: string;
132	  kind: ProviderKind;
133	  key: string;
134	}
135	
136	async function resolveOne(
137	  where: { isPrimary: true } | { isBackup: true }
138	): Promise<ResolvedProvider | null> {
139	  let p;
140	  try {
141	    p = await prisma.aIProvider.findFirst({ where: { ...where, isActive: true } });
142	  } catch {
143	    return null; // table missing / db error → no provider, falls back to default plan
144	  }
145	  if (!p || !p.apiKeyEnc) return null;
146	  let model = "";
147	  try {
148	    const parsed = JSON.parse(p.models);
149	    if (Array.isArray(parsed) && parsed.length) model = String(parsed[0]);
150	  } catch {
151	    /* no model */
152	  }
153	  if (!model) return null;
154	  let key: string;
155	  try {
156	    key = decryptSecret(p.apiKeyEnc);
157	  } catch {
158	    return null;
159	  }
160	  return { id: p.id, name: p.name, baseUrl: p.baseUrl, model, kind: providerKind(p.baseUrl), key };
161	}
