163	/** The active primary / backup providers with decrypted keys — server-only. */
164	export async function resolvePlanProviders(): Promise<{
165	  primary: ResolvedProvider | null;
166	  backup: ResolvedProvider | null;
167	}> {
168	  let [primary, backup] = await Promise.all([
169	    resolveOne({ isPrimary: true }),
170	    resolveOne({ isBackup: true }),
171	  ]);
172	
173	  if (!primary && process.env.AI_PRIMARY_API_KEY) {
174	    const baseUrl = process.env.AI_PRIMARY_BASE_URL || "https://api.anthropic.com/v1/messages";
175	    primary = {
176	      id: "env-primary",
177	      name: "Primary AI (ENV)",
178	      baseUrl,
179	      model: process.env.AI_PRIMARY_MODEL || "claude-3-5-sonnet-20241022",
180	      kind: providerKind(baseUrl),
181	      key: process.env.AI_PRIMARY_API_KEY,
182	    };
183	  }
184	
185	  if (!backup && (process.env.AI_BACKUP_API_KEY || process.env.GEMINI_API_KEY)) {
186	    const key = process.env.AI_BACKUP_API_KEY || process.env.GEMINI_API_KEY || "";
187	    const rawBase = process.env.AI_BACKUP_BASE_URL || "https://generativelanguage.googleapis.com/v1beta";
188	    const baseUrl = rawBase.replace(/\/+$/, "").replace(/\/models$/, "");
189	    backup = {
190	      id: "env-backup",
191	      name: "Backup AI (ENV)",
192	      baseUrl,
193	      model: process.env.AI_BACKUP_MODEL || "gemini-2.0-flash-lite",
194	      kind: providerKind(baseUrl),
195	      key,
196	    };
197	  }
198	
199	  // A backup that's the same provider as the primary is not a real fallback —
200	  // ignore it so retrying actually hits a different provider.
201	  if (primary && backup && backup.id === primary.id) {
202	    return { primary, backup: null };
203	  }
204	  return { primary, backup };
205	}
